async function loadTrainingCenterV2(){
  const content=document.getElementById('content'); if(!content||state.view!=='training')return;
  if(trainingLoadPromiseV2){try{await trainingLoadPromiseV2;}catch{}return;}
  trainingLoadPromiseV2=(async()=>{
    try{
      // V55.10.1: cap the secondary Training request. If it stalls, keep the
      // already-rendered bootstrap Training Center instead of showing Loading forever.
      const r=await Promise.race([
        api('/api/training',{timeoutMs:8000}),
        new Promise((_,reject)=>setTimeout(()=>reject(new Error('Training admin sync timed out; using current workspace data.')),8500))
      ]);
      if(state.view!=='training')return;
      state.data=state.data||{}; state.data.trainingCenter=r;
      const recoveryNotice=r.recoveryRequired?'<div class="install-tip" role="status"><strong>RECOVERY LOCK ACTIVE — READ ONLY.</strong> Training courses can be viewed. Progress, assessments, assignments and certifications are paused until authoritative MySQL recovery is verified.</div>':'';
      content.innerHTML=recoveryNotice+renderTrainingV2(r);
      wireTrainingV2();
    }catch(e){
      if(state.view!=='training')return;
      // If bootstrap already supplied Training data, leave that screen intact.
      // Only show an error when there is genuinely no Training payload at all.
      if(state.data?.trainingCenter){
        try{wireTrainingV2();}catch{}
        console.warn('[SBC TRAINING] secondary admin sync unavailable; bootstrap Training remains active:',e?.message||e);
        return;
      }
      content.innerHTML=shell('SBC Training Center','Training system needs attention',`<div class="card section"><div class="card-body"><div class="install-tip">Training Center could not initialize: ${esc9(e.message||e)}</div><div class="mini" style="margin-top:8px">Your other Command Center areas are unaffected.</div><div class="actions" style="margin-top:14px"><button class="btn primary" onclick="loadTrainingCenterV2()">↻ Retry Training</button></div></div></div>`);
    } finally { trainingLoadPromiseV2=null; }
  })();
  await trainingLoadPromiseV2;
}
function renderTrainingV2(r){
  if(r.mode==='admin')return renderTrainingAdminV2(r);
  const assigned=r.assigned||[],available=r.available||[],progress=r.progress||[],attempts=r.attempts||[],certs=r.certifications||[];
  const passed=progress.filter(x=>x.status==='passed').length,failed=progress.filter(x=>x.status==='failed').length;
  const done=progress.filter(x=>['completed','passed'].includes(x.status)).length;
  const total=assigned.reduce((n,x)=>n+(x.course?.modules||[]).length,0),pct=total?Math.round(done/total*100):0;
  const courses=[...assigned.map(x=>({course:x.course,summary:x.summary,assigned:true})),...available.map(c=>({course:c,summary:null,assigned:false}))];
  return shell('SBC Training Center','SBC Academy · Learn → Practice → Complete → Review',`
    <div class="academy-head">
      <div><div class="academy-eyebrow">SBC ACADEMY</div><h2>Training Center</h2><p>Formal training workspace for learning, practice, assessment and completion.</p></div>
      <div class="academy-progress"><strong>${pct}%</strong><span>overall progress</span><div><i style="width:${pct}%"></i></div><small>${done}/${total||0} assigned modules complete</small></div>
    </div>
    <div class="academy-stats">
      <div><span>COURSES</span><b>${courses.length}</b></div>
      <div><span>PASSED</span><b>${passed}</b></div>
      <div><span>FAILED</span><b>${failed}</b></div>
      <div><span>CERTIFICATIONS</span><b>${certs.filter(x=>x.status==='Certified').length}</b></div>
    </div>
    <div class="academy-toolbar">
      <input id="academyCourseSearch" type="search" placeholder="Search training courses…" aria-label="Search training courses" oninput="filterAcademyCourses()">
      <button type="button" class="btn" onclick="document.getElementById('academyCourseSearch').value='';filterAcademyCourses()">Clear</button>
    </div>
    <section class="academy-section">
      <div class="academy-section-head"><div><h3>Training Library</h3><p>Select a course and use <strong>OPEN COURSE</strong> to begin.</p></div><span>${courses.length} COURSES</span></div>
      <div id="academyCourseGrid" class="academy-course-grid">
        ${courses.map((x,i)=>academyCourseCard(x.course,x.summary,x.assigned,i)).join('')||'<div class="academy-empty">No training courses are available for your role.</div>'}
      </div>
    </section>
    <section class="academy-history">
      <div><strong>Training History</strong><span>${attempts.length} assessment attempts retained</span></div>
      <div class="actions"><button class="btn primary" onclick="trainingMyHistoryV2()">View History</button><button class="btn" onclick="openSbcAI('Review my SBC training progress and tell me what I should study next based only on my current training records.')">🤖 Ask Kim</button></div>
    </section>`);
}
