async function openTrainingCourseV2(id){
  try{if(typeof window.sbcTrainingTelemetry==='function')await window.sbcTrainingTelemetry('opened',id,null);
    const r=await api('/api/training/courses/'+encodeURIComponent(id),{timeoutMs:30000});
    const c=r.course;
    if(!c||!Array.isArray(c.modules))throw new Error('Training course data was not returned correctly.');
    state.trainingCourse=c;state.trainingCourseSummary=r.summary||{};state.trainingModule=null;state.view='training';closeModal();render();
  }catch(e){toast(e?.message||'The training course could not be opened.');}
}
async function openTrainingModuleV2(courseId,moduleId){
  try{if(typeof window.sbcTrainingTelemetry==='function')await window.sbcTrainingTelemetry('started',courseId,moduleId);
    const r=await api('/api/training/courses/'+encodeURIComponent(courseId),{timeoutMs:30000});
    const c=r.course,m=(c?.modules||[]).find(x=>x.id===moduleId);
    if(!c||!m)throw new Error('Training lesson was not found.');
    state.trainingCourse=c;state.trainingCourseSummary=r.summary||{};state.trainingModule=moduleId;state.view='training';closeModal();render();
  }catch(e){toast(e?.message||'The training lesson could not be opened.');}
}
async function addTrainingModuleV2(courseId){openModal('＋ Add Training Module',`<form id="newTrainingModuleV2"><label>Module title<input name="title" required></label><label>Minutes<input type="number" name="minutes" value="15" min="1"></label><label>Description<textarea name="description" rows="4"></textarea></label><label>Objective<textarea name="objective" rows="3"></textarea></label><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Create Draft Module</button></div></form>`);document.getElementById('newTrainingModuleV2').onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.lesson={objective:x.objective||x.description,learn:[],practice:{prompt:'Demonstrate the skill.',evidence:'Record evidence.'},knowledgeCheck:{prompt:'Explain the rule.',passingRule:'Accurate and specific.'}};delete x.objective;try{await api('/api/training/courses/'+encodeURIComponent(courseId)+'/modules',{method:'POST',body:JSON.stringify(x)});closeModal();await reload();toast('Draft module created.');}catch(err){toast(err.message)}}}
function wireTrainingV2(){
  document.querySelectorAll('.training-open-course').forEach(btn=>{
    if(btn.dataset.trainingWired==='1')return;
    btn.dataset.trainingWired='1';
    btn.addEventListener('click',()=>{
      const id=btn.getAttribute('data-course-id');
      if(id) openTrainingCourseV2(id);
    });
  });
}
