// Non-intrusive Kim operational alert overlay. It only appears for concrete rule-based urgent conditions.
let kimAttentionTimer=null,kimDismissed={},kimAttentionInFlight=false;
async function pollKimAttention(){if(document.visibilityState==='hidden'||!window.state?.me||kimAttentionInFlight)return;kimAttentionInFlight=true;try{const r=await api('/api/ai/attention',{timeoutMs:8000});const a=(r.alerts||[]).find(x=>x.level==='urgent'&&!kimDismissed[x.id]);if(!a)return;const old=document.getElementById('kimUrgentOverlay');if(old)return;document.body.insertAdjacentHTML('beforeend',`<div id="kimUrgentOverlay" class="kim-urgent-overlay"><div class="kim-urgent-card"><div class="eyebrow">🤖 KIM · URGENT OPERATIONAL MESSAGE</div><h2>${esc9(a.title)}</h2><p>${esc9(a.message)}</p><div class="actions"><button class="btn" onclick="kimDismissUrgent('${a.id}')">Dismiss</button><button class="btn primary" onclick="kimTakeUrgent('${a.id}','${a.view||'dashboard'}')">${esc9(a.action||'Open Now')}</button></div></div></div>`);}catch(e){}finally{kimAttentionInFlight=false}}
function kimDismissUrgent(id){kimDismissed[id]=true;document.getElementById('kimUrgentOverlay')?.remove()}
function kimTakeUrgent(id,view){kimDismissed[id]=true;document.getElementById('kimUrgentOverlay')?.remove();state.view=view;render()}
window.addEventListener('DOMContentLoaded',()=>{setTimeout(loadLeadAssistSummary,1200);clearInterval(kimAttentionTimer);kimAttentionTimer=setInterval(pollKimAttention,30000);setTimeout(pollKimAttention,5000);});
